import{_ as t,a as e}from"./chunks/image11.DgqECnCK.js";import{_ as a,o as r,c as i,ak as n}from"./chunks/framework.C7PCA8hc.js";const l="/projects/miniAutopro/en/latest/assets/image3.lpny2yac.webp",s="/projects/miniAutopro/en/latest/assets/image5.Bm-IhMYI.webp",A="data:image/png;base64,",c="data:image/png;base64,",d="data:image/png;base64,",m="/projects/miniAutopro/en/latest/assets/image9.Cy1Vfu1L.webp",v=JSON.parse('{"title":"3. Factory Program Download","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Factory Program Download.md","filePath":"docs/3. Factory Program Download.md"}'),g={name:"docs/3. Factory Program Download.md"};function p(h,o,u,f,b,P){return r(),i("div",null,[...o[0]||(o[0]=[n('<h1 id="_3-factory-program-download" tabindex="-1">3. Factory Program Download <a class="header-anchor" href="#_3-factory-program-download" aria-label="Permalink to &quot;3. Factory Program Download&quot;">​</a></h1><h2 id="_3-1-program-download" tabindex="-1">3.1 Program Download <a class="header-anchor" href="#_3-1-program-download" aria-label="Permalink to &quot;3.1 Program Download&quot;">​</a></h2><p id="p3-1"></p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p><strong>When connecting the Type-C download cable, toggle the battery switch to OFF to prevent the download cable from accidentally contacting the power pins of the expansion board and causing a short circuit.</strong></p></li><li><p><strong>The following steps use the motor automatic calibration program as a download reference.</strong></p></li></ul></div><ol><li>Locate and double-click the <strong>.ino</strong> file <strong>miniAutoPro-test.ino</strong> under the same directory as this document at <a href="https://drive.google.com/drive/folders/1lHrFVQHmhJXSctcVvKjF4TJkubi85MrA?usp=sharing" target="_blank" rel="noreferrer">Program Files/3.1 Encoder Motor Automatic Calibration Example/miniAutoPro-test/miniAutoPro-test.ino</a>.</li></ol><img loading="lazy" height="135" width="391" src="'+l+'" class="common_img" style="width:400px;"><ol start="2"><li>Connect the ESP32 robot car board to the computer using a Type-C data cable.</li></ol><img loading="lazy" height="550" width="826" src="'+t+'" class="common_img" style="width:800px;"><ol start="3"><li>Select the development board model and communication port, as shown below:</li></ol><img loading="lazy" height="237" width="510" src="'+s+'" class="common_img" style="width:600px;"><ol start="4"><li>Click the upload button <img loading="lazy" height="49" width="48" src="'+A+'" class="inline-icon"> to download the program to the development board, and wait for the upload to complete.</li></ol><img loading="lazy" height="38" width="530" src="'+c+'" class="common_img" style="width:800px;"><img loading="lazy" height="54" width="595" src="'+d+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>If burning fails after clicking the upload button, lower the upload baud rate to 115200 and upload again.</strong></p></div><img loading="lazy" height="657" width="769" src="'+e+'" class="common_img" style="width:800px;"><h2 id="_3-2-motor-automatic-calibration" tabindex="-1">3.2 Motor Automatic Calibration <a class="header-anchor" href="#_3-2-motor-automatic-calibration" aria-label="Permalink to &quot;3.2 Motor Automatic Calibration&quot;">​</a></h2><p id="p3-2"></p><h3 id="_3-2-1-program-download" tabindex="-1">3.2.1 Program Download <a class="header-anchor" href="#_3-2-1-program-download" aria-label="Permalink to &quot;3.2.1 Program Download&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p><strong>Refer to <a href="#p3-1">Section 3.1 Program Download</a>. Select the program located at <a href="https://drive.google.com/drive/folders/1lHrFVQHmhJXSctcVvKjF4TJkubi85MrA?usp=sharing" target="_blank" rel="noreferrer">Program Files/3.1 Encoder Motor Automatic Calibration Example/miniAutoPro-test/miniAutoPro-test.ino</a> for download.</strong></p></li><li><p><strong>This step is a prerequisite for all subsequent functions. Normal operation of the default factory program, including app remote control and AI voice control, relies on the motor dead zones and feedforward parameters calibrated in this section. Motor automatic calibration must be completed before downloading and running the factory program, otherwise the robot car will move abnormally.</strong></p></li></ul></div><h3 id="_3-2-2-program-outcome" tabindex="-1">3.2.2 Program Outcome <a class="header-anchor" href="#_3-2-2-program-outcome" aria-label="Permalink to &quot;3.2.2 Program Outcome&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Automatic calibration takes approximately 3 minutes. The buzzer sounds twice: the first time signals system startup, and the second time confirms calibration completion. Confirm successful calibration only after the second buzzer prompt sounds and the robot car begins moving forward. Do not disconnect the power during this process.</strong></p></div><p>After the program download is complete, power on the robot car. The system executes the following sequence:</p><ol><li><p><strong>Device Self-Test</strong>: The serial monitor outputs the expansion board device ID, the firmware version, and the current battery voltage, displayed in both millivolts and volts.</p></li><li><p><strong>Buzzer Startup Prompt</strong>: The buzzer emits three ascending tones in sequence, indicating that the system has started.</p></li><li><p><strong>Automatic Calibration of 4-Channel Encoder Motors</strong>: The chassis driver board automatically calibrates the 4 motors sequentially in forward and reverse directions. It measures and records forward and reverse starting dead zones, representing minimum starting PWM values, running dead zones, representing minimum running PWM values, and feedforward parameters in PWM per RPM. The calibration process allows a maximum timeout of 300 s. If a timeout or failure occurs, corresponding error messages appear in the serial monitor.</p></li><li><p><strong>Calibration Result Output</strong>: After successful calibration, the serial monitor outputs complete calibration data for the 4 motors in forward and reverse directions, including starting dead zones, running dead zones, and feedforward coefficients.</p></li><li><p><strong>Calibration Completion Prompt</strong>: The buzzer emits three descending tones in reverse sequence, confirming successful calibration.</p></li><li><p><strong>Motion Verification Test</strong>: The robot car travels forward at a speed of 0.15 m/s for 10 s and stops automatically, verifying that motor drive and chassis motion functions operate normally.</p></li></ol><img loading="lazy" height="350" width="421" src="'+m+'" class="common_img" style="width:600px;"><h2 id="_3-3-factory-program-download" tabindex="-1">3.3 Factory Program Download <a class="header-anchor" href="#_3-3-factory-program-download" aria-label="Permalink to &quot;3.3 Factory Program Download&quot;">​</a></h2><p>This section covers the procedure for downloading the default factory program to the robot car.</p><h3 id="_3-3-1-program-download" tabindex="-1">3.3.1 Program Download <a class="header-anchor" href="#_3-3-1-program-download" aria-label="Permalink to &quot;3.3.1 Program Download&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p><strong>Refer to <a href="#p3-1">Section 3.1 Program Download</a>. Select the program located at <a href="https://drive.google.com/drive/folders/1GtX9WHeNXC5QKwYgvH1sidxqE4W3BQkS?usp=sharing" target="_blank" rel="noreferrer">Program Files/3.2 Factory Program Download/MiniAutoPro_Default/MiniAutoPro_Default.ino</a> for download.</strong></p></li><li><p><strong>Before running the program, <a href="#p3-2">Section 3.2 Motor Automatic Calibration</a> must be completed. Otherwise, the robot car will experience abnormal movements, such as failing to travel straight or deviating during turns.</strong></p></li></ul></div><h3 id="_3-3-2-program-outcome" tabindex="-1">3.3.2 Program Outcome <a class="header-anchor" href="#_3-3-2-program-outcome" aria-label="Permalink to &quot;3.3.2 Program Outcome&quot;">​</a></h3><p>After the program download is complete, power on the robot car. The serial monitor outputs system initialization information. The Mecanum-wheel chassis, BLE Bluetooth, ultrasonic sensor, and robotic arm servos initialize sequentially, and the buzzer emits a startup prompt tone.</p><p>The default factory program integrates the following features:</p><ol><li><p><strong>miniAuto App Bluetooth Remote Control</strong>: Supports joystick control, ultrasonic obstacle avoidance, RGB color adjustment, gripper and robotic arm control, and sensor telemetry transmission. For detailed instructions, refer to <a href="https://drive.google.com/drive/folders/1CdosFVO9Cjm60kIgvJp4rkdl_YyTHpXn?usp=sharing" target="_blank" rel="noreferrer">4. Quick Start</a>.</p></li><li><p><strong>WonderLLM AI Voice Interaction</strong>: When equipped with the WonderLLM module, natural language commands entered through the online chat interface in the app control the movement of the car and robotic arm actions. For detailed instructions, refer to subsequent AI model fundamental tutorials.</p></li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p><strong>If the WonderLLM module is not detected at startup, the program automatically retries initialization every 5 s, during which the app remote control function remains unaffected.</strong></p></li><li><p><strong>App remote control and AI voice interaction can be used simultaneously, as internal control coordination is implemented within the program.</strong></p></li></ul></div>',33)])])}const k=a(g,[["render",p]]);export{v as __pageData,k as default};
